	@Test
	void scheduledSemiAntiExactCacheHitRetainsOriginatingAlgorithmEvent() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern provider = new StatementPattern(Var.of("provider"),
				Var.of("providerPredicate", values.createIRI("urn:provider"), true, true), Var.of("gate"));
		StatementPattern continuation = new StatementPattern(Var.of("gate"),
				Var.of("continuationPredicate", values.createIRI("urn:continuation"), true, true), Var.of("value"));
		StatementPattern dependent = new StatementPattern(Var.of("gate"),
				Var.of("dependentPredicate", values.createIRI("urn:dependent"), true, true), Var.of("dependentValue"));
		Filter filter = new Filter(new Join(provider, continuation), new Not(new Exists(dependent)));
		PackedCostModel model = new PackedCostModel() {

			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return query.isStatementPattern(relationId) ? 10.0d : Double.NaN;
			}

			@Override
			public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (query.isAntiJoin(relationId) || query.isFilter(relationId)) {
					output.setContextualOutputRowsPreservingPhysicalCost(context.leftInputRows() * 0.8d);
					output.setLocalPhysicalCost(1.0d, 0.0d, 0.0d, context.leftInputRows(), 0.0d, 0.0d,
							0.0d, context.leftInputRows() * 0.8d, 0.0d, 0.0d);
					output.setDependentSubqueriesCosted(true);
				}
			}
		};
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanCache.Context context = new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L);

		PackedPlanningResult cold = PackedCascadesPlanner.optimize(filter, OptimizationGoal.root(), cache, context,
				model);
		PackedPlanningResult hot = PackedCascadesPlanner.optimize(filter.clone(), OptimizationGoal.root(), cache,
				context, model);
		Filter coldFilter = findSemiAntiFilter(cold.selectedPlan());
		Filter hotFilter = findSemiAntiFilter(hot.selectedPlan());

		assertNotNull(coldFilter, cold.selectedPlan()::toString);
		assertNotNull(hotFilter, hot.selectedPlan()::toString);
		assertEquals(coldFilter.getStringMetricPlanned("optimizer.semiAntiAlgorithm"),
				hotFilter.getStringMetricPlanned("optimizer.semiAntiAlgorithm"));
		assertEquals(coldFilter.getStringMetricPlanned("optimizer.semiAntiKind"),
				hotFilter.getStringMetricPlanned("optimizer.semiAntiKind"));
		assertEquals(coldFilter.getStringMetricPlanned("optimizer.costEventDigest"),
				hotFilter.getStringMetricPlanned("optimizer.costEventDigest"));
		assertTrue(hot.metrics().planCacheHit());
	}

	@Test
	void scheduledSemiAntiLocalCostIncludesItsSelectedPrefix() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern provider = new StatementPattern(Var.of("provider"),
				Var.of("providerPredicate", values.createIRI("urn:provider"), true, true), Var.of("gate"));
		StatementPattern continuation = new StatementPattern(Var.of("continuation"),
				Var.of("continuationPredicate", values.createIRI("urn:continuation"), true, true), Var.of("value"));
		StatementPattern dependent = new StatementPattern(Var.of("gate"),
				Var.of("dependentPredicate", values.createIRI("urn:dependent"), true, true), Var.of("dependentValue"));
		Filter filter = new Filter(new Join(provider, continuation), new Not(new Exists(dependent)));
		PackedCostModel model = new PackedCostModel() {

			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				if (!query.isStatementPattern(relationId)) {
					return Double.NaN;
				}
				return query.materializeRelation(relationId).equals(provider) ? 10.0d : 100.0d;
			}

			@Override
			public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (query.isFilter(relationId)) {
					output.setContextualOutputRowsPreservingPhysicalCost(context.leftInputRows() * 0.5d);
					output.setLocalPhysicalCost(20.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
					output.setDependentSubqueriesCosted(true);
				}
			}
		};

		PackedQuery query = PackedQueryCodec.encodeForPlanning(filter);
		int relationCount = query.relationCount();
		PackedMemo memo = new PackedMemo(query, query.symbolCount(), relationCount, relationCount, 4,
				relationCount, relationCount * 2);
		PackedSearchBudget budget = new PackedSearchBudget(Long.MAX_VALUE, Long.MAX_VALUE);
		PackedIncumbentSearch search = new PackedIncumbentSearch(query, memo, budget, false, model);
		search.build();
		PackedJoinEnumerator enumerator = new PackedJoinEnumerator(
				query, memo, search.selectedRowsByGroup(), budget, model);

		int workUnits = enumerator.seedCorrelatedFilter(query.rootRelId());
		int rootWinnerId = memo.findWinner(memo.logicalGroupId(query.rootRelId()), memo.anyPropertyId(), 0, 0, 0);

		assertEquals(2, workUnits);
		/*
		 * Provider scan (10) + scheduled local semi/anti work (20) leaves five rows. The disconnected continuation pays
		 * one startup unit plus five rebinds of its remaining 99 work units, then produces 500 join rows.
		 */
		assertEquals(1_026.0d, memo.winnerTotalCost(rootWinnerId),
				"a scheduled LOCAL semi/anti vector must retain invocation-aware continuation work");
	}

	private static StatementPattern input() {
		return new StatementPattern(Var.of("subject"), Var.of("predicate"), Var.of("object"));
	}

	private static int relationId(PackedQuery query, TupleExpr expression) {
		PackedQueryView view = new PackedQueryView(query);
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (view.materializeRelation(relationId).equals(expression)) {
				return relationId;
			}
		}
		throw new AssertionError("missing packed relation for " + expression);
	}

	private static Filter findSemiAntiFilter(TupleExpr expression) {
		Filter[] result = new Filter[1];
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (result[0] == null && node instanceof Filter filter
						&& filter.getStringMetricPlanned("optimizer.semiAntiAlgorithm") != null) {
					result[0] = filter;
				}
				node.visitChildren(this);
			}
		});
		return result[0];
	}

	private static PackedCostEstimate composedCost() {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setInclusivePhysicalCost(3.0d, 3.0d, 3.0d, 3.0d, 3.0d, 3.0d, 3.0d, 3.0d, 10.0d);
		return estimate;
	}

	private static double physicalDimension(PackedCostEstimate estimate, String methodName) throws Exception {
		return (double) PackedCostEstimate.class.getMethod(methodName).invoke(estimate);
	}

	private static double arenaDimension(PackedPhysicalMetadataArena arena, int metadataId, String methodName)
			throws Exception {
		Method method = PackedPhysicalMetadataArena.class.getDeclaredMethod(methodName, int.class);
		method.setAccessible(true);
		return (double) method.invoke(arena, metadataId);
	}

	private static Object arenaValue(PackedPhysicalMetadataArena arena, int metadataId, String methodName)
			throws Exception {
		Method method = PackedPhysicalMetadataArena.class.getDeclaredMethod(methodName, int.class);
		method.setAccessible(true);
		return method.invoke(arena, metadataId);
	}
